  const options={};
  for (const name of ['q','tag']) if (params.has(name)) options[name]=params.get(name);
  if (numeric) for (const name of ['limit','offset']) if (params.has(name)) {
    if (!/^\d+$/.test(params.get(name))) throw new Error(`${name} must be an integer`);
