    if (path==='/api/import' && method==='POST') return send(res,201,importNotes(store,(await body(req)).notes));
    if (path==='/' && method==='GET') return html(res,200,dashboard(url));
    const edit=path.match(/^\/notes\/(\d+)\/edit$/);
    if (edit && method==='GET') {
