import { DatabaseSync } from 'node:sqlite';
import { mkdirSync } from 'node:fs';
import { dirname } from 'node:path';
import { normalizeText, normalizeTags, normalizeTag, validId, object } from './validation.mjs';

export function openStore(path) {
  if (path !== ':memory:') mkdirSync(dirname(path), {recursive:true});
  const db = new DatabaseSync(path);
  // SQLite's built-in lower() is ASCII-only; use JS for Unicode casing.
  db.function('casefold',{deterministic:true},value=>value.toLowerCase());
  db.exec(`PRAGMA foreign_keys=ON; PRAGMA busy_timeout=5000;
    CREATE TABLE IF NOT EXISTS notes(id INTEGER PRIMARY KEY,text TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
    CREATE TABLE IF NOT EXISTS tags(name TEXT PRIMARY KEY);
    CREATE TABLE IF NOT EXISTS note_tags(note_id INTEGER REFERENCES notes(id) ON DELETE CASCADE,tag TEXT REFERENCES tags(name),PRIMARY KEY(note_id,tag));`);
  let depth = 0;
  const transaction = fn => {
    if (depth) return fn();
    db.exec('BEGIN IMMEDIATE'); depth++;
    try { const result = fn(); db.exec('COMMIT'); return result; }
    catch (error) { db.exec('ROLLBACK'); throw error; }
    finally { depth--; }
  };
  const getNote = id => {
    validId(id);
    const row = db.prepare('SELECT * FROM notes WHERE id=?').get(id);
    if (!row) return null;
    return {id:Number(row.id),text:row.text,createdAt:row.created_at,updatedAt:row.updated_at,
      tags:db.prepare('SELECT tag FROM note_tags WHERE note_id=? ORDER BY tag').all(id).map(r=>r.tag)};
  };
  const attach = (id,tags) => {
    for (const tag of tags) {
      db.prepare('INSERT OR IGNORE INTO tags(name) VALUES(?)').run(tag);
      db.prepare('INSERT INTO note_tags(note_id,tag) VALUES(?,?)').run(id,tag);
    }
  };
  return {
    transaction,
    createNote(text,tags=[]) {
      text = normalizeText(text); tags = normalizeTags(tags);
      return transaction(() => {
        const now = new Date().toISOString();
        const id = Number(db.prepare('INSERT INTO notes(text,created_at,updated_at) VALUES(?,?,?)').run(text,now,now).lastInsertRowid);
        attach(id,tags); return getNote(id);
      });
    },
    getNote,
    listNotes(options={}) {
      object(options);
      const {q,tag,limit=50,offset=0} = options;
      if (!Number.isInteger(limit) || limit<1 || limit>100) throw new Error('limit must be an integer from 1 to 100');
      if (!Number.isSafeInteger(offset) || offset<0) throw new Error('offset must be a nonnegative integer');
      if (q !== undefined && typeof q !== 'string') throw new Error('q must be a string');
      const filters = [], params = [];
      if (q !== undefined) { filters.push('instr(casefold(text),casefold(?))>0'); params.push(q); }
      if (tag !== undefined) { filters.push('EXISTS(SELECT 1 FROM note_tags WHERE note_id=notes.id AND tag=?)'); params.push(normalizeTag(tag)); }
      return db.prepare(`SELECT id FROM notes ${filters.length?'WHERE '+filters.join(' AND '):''} ORDER BY id DESC LIMIT ? OFFSET ?`)
        .all(...params,limit,offset).map(r=>getNote(Number(r.id)));
    },
    updateNote(id,patch) {
      validId(id); object(patch);
      const text = Object.hasOwn(patch,'text') ? normalizeText(patch.text) : undefined;
      const tags = Object.hasOwn(patch,'tags') ? normalizeTags(patch.tags) : undefined;
      return transaction(() => {
        const old = getNote(id); if (!old) return null;
        const now = new Date(Math.max(Date.now(),Date.parse(old.updatedAt)+1)).toISOString();
        db.prepare('UPDATE notes SET text=?,updated_at=? WHERE id=?').run(text??old.text,now,id);
        if (tags !== undefined) { db.prepare('DELETE FROM note_tags WHERE note_id=?').run(id); attach(id,tags); }
        return getNote(id);
      });
    },
    deleteNote(id) { validId(id); return db.prepare('DELETE FROM notes WHERE id=?').run(id).changes>0; },
    listTags() { return db.prepare('SELECT tag AS name,COUNT(*) AS count FROM note_tags GROUP BY tag ORDER BY tag').all().map(r=>({name:r.name,count:Number(r.count)})); },
    close() { db.close(); }
  };
}

export function normalizeText(text) {
  if (typeof text !== 'string' || !text.trim() || text.trim().length > 4000)
    throw new Error('text must contain 1–4000 characters');
  return text.trim();
}
export function normalizeTag(tag) {
  if (typeof tag !== 'string' || !tag.trim() || tag.trim().length > 40)
    throw new Error('tags must be nonempty strings of at most 40 characters');
  return tag.trim().toLowerCase();
}
export function normalizeTags(tags) {
  if (!Array.isArray(tags)) throw new Error('tags must be an array');
  return [...new Set(Array.from(tags,normalizeTag))].sort();
}
export function validId(id) {
  if (!Number.isSafeInteger(id) || id < 1) throw new Error('id must be a positive integer');
  return id;
}
export function object(value) {
  if (!value || typeof value !== 'object' || Array.isArray(value)) throw new Error('expected an object');
  return value;
}

import {test} from 'node:test';
import assert from 'node:assert/strict';
import {mkdtempSync,rmSync} from 'node:fs';
import {join} from 'node:path';
import {openStore} from '../src/store.mjs';
import {importNotes,exportNotes,allNotes} from '../src/import.mjs';

test('normalization, literal filters, pagination and atomic updates',()=>{
  const s=openStore(':memory:');
  try {
    const first=s.createNote('  50%_ DONE  ',[' Work ','work','A']);
    assert.equal(first.text,'50%_ DONE');assert.deepEqual(first.tags,['a','work']);
    const second=s.createNote('other',['work']);
    assert.deepEqual(s.listNotes({q:'%_ doNe'}),[first]);
    assert.deepEqual(s.listNotes({tag:' WORK ',limit:1,offset:1}),[first]);
    assert.deepEqual(s.listNotes().map(n=>n.id),[second.id,first.id]);
    const updated=s.updateNote(first.id,{text:'new',tags:['Next']});
    assert.equal(updated.createdAt,first.createdAt);assert.ok(updated.updatedAt>first.updatedAt);
    assert.deepEqual(updated.tags,['next']);
    assert.throws(()=>s.updateNote(first.id,{text:'changed',tags:['valid',null]}));
    assert.deepEqual(s.getNote(first.id),updated);
    assert.throws(()=>s.createNote('bad',['valid','']));
    assert.equal(s.listNotes().length,2);
    for (const text of [null,3,'','  ','x'.repeat(4001)]) assert.throws(()=>s.createNote(text));
    for (const tags of [null,{},'tag',['x'.repeat(41)],[4],new Array(1)]) assert.throws(()=>s.createNote('ok',tags));
    for (const options of [{limit:0},{limit:101},{limit:1.5},{offset:-1},{offset:1.5},{q:4},{tag:''}]) assert.throws(()=>s.listNotes(options));
    assert.equal(s.getNote(999),null);assert.equal(s.updateNote(999,{}),null);assert.equal(s.deleteNote(999),false);
    assert.equal(s.deleteNote(first.id),true);
    assert.deepEqual(s.listTags(),[{name:'work',count:1}]);
    assert.ok(s.updateNote(second.id,{}).updatedAt>second.updatedAt);
    const unicode=s.createNote('CAFÉ Ελληνικά');
    assert.deepEqual(s.listNotes({q:'café ελληνικά'}),[unicode]);
  } finally {s.close();}
});

test('shared importer validates every field before writes, including later tags',()=>{
  const s=openStore(':memory:');
  try {
    for (const invalid of [{text:' '},{text:'x',tags:null},{text:'x',tags:['']},{text:'x',tags:[false]}]) {
      assert.throws(()=>importNotes(s,[{text:'valid',tags:['good']},invalid]));
      assert.deepEqual(s.listNotes(),[]);assert.deepEqual(s.listTags(),[]);
    }
    const notes=importNotes(s,[{text:' oldest ',tags:['B','b']},{text:'newest'}]);
    assert.deepEqual(exportNotes(s),{version:1,notes:[{text:'oldest',tags:['b']},{text:'newest',tags:[]}]});
    assert.deepEqual(allNotes(s),notes.toReversed());
    assert.throws(()=>s.transaction(()=>{s.createNote('rolled back');throw new Error('abort');}));
    assert.equal(s.listNotes().length,2);
  } finally {s.close();}
});

test('persistence, parent creation and complete exports beyond 100 records',()=>{
  const dir=mkdtempSync(join(process.cwd(),'test/.db-'));
  const path=join(dir,'nested','notes.sqlite');
  let s=openStore(path);
  try {
    for (let i=0;i<125;i++) s.createNote(`note ${i}`,['count']);
    s.close();s=openStore(path);
    assert.equal(allNotes(s).length,125);
    assert.equal(exportNotes(s).notes[0].text,'note 0');
    assert.deepEqual(s.listTags(),[{name:'count',count:125}]);
  } finally {s.close();rmSync(dir,{recursive:true,force:true});}
});

